insert into public.studies (content_id, kind, body, reading_minutes, bible_reference) values (md5('content:noe-confiou-em-deus')::uuid, 'historia', 'Noé vivia em um tempo em que quase ninguém se lembrava de Deus. Mesmo assim, ele escolheu ouvir e obedecer.
insert into public.studies (content_id, kind, body, reading_minutes, bible_reference) values (md5('content:coragem-como-a-de-daniel')::uuid, 'estudo', 'Daniel orava três vezes por dia, com a janela aberta. Quando o rei proibiu as orações, Daniel continuou orando.
insert into public.studies (content_id, kind, body, reading_minutes, bible_reference) values (md5('content:versiculo-joao-3-16')::uuid, 'versiculo', '> "Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna."
